package com.mamtrex.hospital.surgery;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="surgical_cases") public class SurgicalCase extends BaseEntity { private String patientId; private String procedureName; private String surgeonId; private String scheduledAt; private String status; protected SurgicalCase(){} public SurgicalCase(String patientId, String procedureName, String surgeonId, String scheduledAt, String status){this.patientId=patientId; this.procedureName=procedureName; this.surgeonId=surgeonId; this.scheduledAt=scheduledAt; this.status=status;} public String getPatientId(){return patientId;} public String getProcedureName(){return procedureName;} public String getSurgeonId(){return surgeonId;} public String getScheduledAt(){return scheduledAt;} public String getStatus(){return status;} }
